        align: {
          anyOf: [
            { $ref: "#/definitions/LayoutAlign" },
            { $ref: "#/definitions/RowCol<LayoutAlign>" },
          ],
          description:
            'The alignment to apply to grid rows and columns. The supported string values are `"all"`, `"each"`, and `"none"`.\n\n- For `"none"`, a flow layout will be used, in which adjacent subviews are simply placed one after the other.\n- For `"each"`, subviews will be aligned into a clean grid structure, but each row or column may be of variable size.\n- For `"all"`, subviews will be aligned and each row or column will be sized identically based on the maximum observed size. String values for this property will be applied to both grid rows and columns.\n\nAlternatively, an object value of the form `{"row": string, "column": string}` can be used to supply different alignments for rows and columns.\n\n__Default value:__ `"all"`.',
        },
        autosize: {
          anyOf: [
            { $ref: "#/definitions/AutosizeType" },
            { $ref: "#/definitions/AutoSizeParams" },
          ],
          description:
            'How the visualization size should be determined. If a string, should be one of `"pad"`, `"fit"` or `"none"`. Object values can additionally specify parameters for content sizing and automatic resizing.\n\n__Default value__: `pad`',
        },
        background: {
          anyOf: [{ $ref: "#/definitions/Color" }, { $ref: "#/definitions/ExprRef" }],
          description:
            'CSS color property to use as the background of the entire view.\n\n__Default value:__ `"white"`',
        },
        bounds: {
          description:
            'The bounds calculation method to use for determining the extent of a sub-plot. One of `full` (the default) or `flush`.\n\n- If set to `full`, the entire calculated bounds (including axes, title, and legend) will be used.\n- If set to `flush`, only the specified width and height values for the sub-view will be used. The `flush` setting can be useful when attempting to place sub-plots without axes or legends into a uniform grid structure.\n\n__Default value:__ `"full"`',
          enum: ["full", "flush"],
          type: "string",
        },
        center: {
          anyOf: [{ type: "boolean" }, { $ref: "#/definitions/RowCol<boolean>" }],
          description:
            'Boolean flag indicating if subviews should be centered relative to their respective rows or columns.\n\nAn object value of the form `{"row": boolean, "column": boolean}` can be used to supply different centering values for rows and columns.\n\n__Default value:__ `false`',
        },
